                                            client.Entity.AddTopStatus(Update.Flags.TopWaterTaoist, DateTime.Now.AddDays(7));
                                            client.Inventory.Add(723715, 0, 1);
                                            client.Entity.SendSpawn(client, true);
                                            client.Entity.Teleport(1002, 429, 378);
                                            EntityTable.SaveEntity(client);
                                        }
                                        else
                                        {
                                            dialog.Text(" tem " + alive + " jogadores que você deve matar para pegar o premio!");
                                            dialog.Option("ok", 255);
                                            dialog.Send();
                                            break;
                                        }
                                    }
                                    else
                                    {
                                        dialog.Text("ola " + client.Entity.Name + " você só pode requerer o premio depois de 19:30");
                                        dialog.Option("ok", 255);
                                        dialog.Send();
                                        break;
                                    }
                                    break;
                                }
                        }
                        break;
                    }
                #endregion
                #region Torneo Arquero
                case 90032:
                    {
                        switch (npcRequest.OptionID)
                        {
                            case 0:
                                {
                                    dialog.Text("quer ir ao torneio só pode  entrar entre 13:05 a 13:30, se não é archer oque faz aqui");
                                    dialog.Option("leva me até esse torneio.", 1);
                                    dialog.Option("não me enteressa.", 255);
                                    dialog.Send();
                                    break;
                                }
                            case 1:
                                {
                                    if (DateTime.Now.DayOfWeek == DayOfWeek.Tuesday && DateTime.Now.Hour == 13 && DateTime.Now.Minute >= 05 && DateTime.Now.Minute < 30)
                                    {

                                        if (client.Entity.Class >= 40 && client.Entity.Class <= 45)
                                        {
                                            client.Entity.Teleport(9008, 40, 50);
                                        }
                                    }
                                    else
                                    {
                                        dialog.Text("ou você não é archer ou ainda não esta na hora");
                                        dialog.Option("acho que sou noob!", 255);
                                        dialog.Send();
                                    }
                                    break;
                                }
                        }
                        break;
                    }
                #endregion
                #region Premio Arquero
                case 90033:
                    {
                        switch (npcRequest.OptionID)
                        {
                            case 0:
                                {
                                    dialog.Text("ola " + client.Entity.Name + " quer pega o premio?");
                                    dialog.Option("Sim!", 1);
                                    dialog.Option("Não.", 255);
                                    dialog.Send();
                                    break;
                                }
                            case 1:
                                {
                                    int alive = 0;
                                    foreach (Conquer_Online_Server.Client.GameClient players in Conquer_Online_Server.Kernel.GamePool.Values)
                                        if (players.Entity.MapID == 9008 && (!players.Entity.Dead))
                                            alive++;
                                    if (DateTime.Now.DayOfWeek == DayOfWeek.Tuesday && DateTime.Now.Hour == 13 && DateTime.Now.Minute >= 30 && DateTime.Now.Minute < 59)
                                    {
                                        if (alive == 1)
                                        {
                                            client.Entity.ConquerPoints += 500000;
                                            client.Entity.AddTopStatus(Update.Flags.TopArcher, DateTime.Now.AddDays(7));
                                            client.Inventory.Add(723715, 0, 1);
                                            client.Entity.SendSpawn(client, true);
                                            client.Entity.Teleport(1002, 429, 378);
                                            EntityTable.SaveEntity(client);
                                        }
                                        else
                                        {
                                            dialog.Text(" tem " + alive + " jogadores que você deve matar para pegar o premio!");
                                            dialog.Option("ok", 255);
                                            dialog.Send();
                                            break;
                                        }
                                    }
                                    else
                                    {
                                        dialog.Text("ola " + client.Entity.Name + " você só pode requerer o premio depois de 19:30");
                                        dialog.Option("ok", 255);
                                        dialog.Send();
                                        break;
                                    }
                                    break;
                                }
                        }
                        break;
                    }
                #endregion
                #region Treansportar Torneo
                    case 90000:
                                {

                                    switch (npcRequest.OptionID)
                                    {
                                        case 0:
                                            {
                                                dialog.Text("Ola Posso transportar você para area de pk de classes ?.");
                                                dialog.Option("Deseja ir.", 1);
                                                dialog.Option("Não Obrigado!", 255);
                                                dialog.Send();
                                                break;
                                            }
                                        case 1:
                                            {
                                                client.Entity.Teleport(9000, 436, 375);
                                                break;
                                                 }
                                        }
                               break;
                            }           

                     #endregion
                #endregion
                    default:
                    {
                        if (client.ActiveNpc >= 101002 && client.Entity.MapID == 10002)
                        {
                            client.SendScreen(new Network.GamePackets.Data(true) { UID = client.ActiveNpc, ID = Network.GamePackets.Data.RemoveEntity }, true);
                            client.Map.RemoveNpc(client.Map.Npcs[client.ActiveNpc]);
                            Conquer_Online_Server.Game.TreasureBox.Reward(client);
                        }
                        if (client.Account.State == Conquer_Online_Server.Database.AccountTable.AccountState.GameMaster || client.Account.State == Conquer_Online_Server.Database.AccountTable.AccountState.ProjectManager)
                            client.Send(new Message("NpcID[" + client.ActiveNpc + "]", System.Drawing.Color.Red, Message.TopLeft));
                        break;
                    }
            }

            if (!dialog.Sent)
                if (dialog.Replies.Count > 1)
                    dialog.Send();
        }
    }
}


